+                                .event("session_projection")
+                                .data(data)))
+                            .await
+                            .is_err()
+                        {
+                            return;
+                        }
+                    }
+                    continue;
+                }
+                Ok(_) => {}
+                Err(reset) => {
+                    let data = json!({
+                        "type": "projection_reset",
+                        "reason": reset.reason(),
+                    })
+                    .to_string();
+                    let _ = tx
+                        .send(Ok(Event::default().event("projection_reset").data(data)))
+                        .await;
+                    return;
+                }
+            }
+
+            tokio::select! {
+                _ = shutdown.cancelled() => return,
+                _ = tx.closed() => return,
+                wake = wakes.recv() => match wake {
+                    Ok(woken_session) if woken_session == session_id => {},
+                    Ok(_) => continue,
+                    Err(tokio::sync::broadcast::error::RecvError::Lagged(_)) => {},
+                    Err(tokio::sync::broadcast::error::RecvError::Closed) => return,
+                }
+            }
+        }
+    });
+
+    Sse::new(ReceiverStream::new(rx)).keep_alive(KeepAlive::new().interval(SSE_KEEPALIVE_INTERVAL))
+}
