//! Durable, session-scoped snapshot/tail projection for first-party surfaces.
//!
//! Session JSON remains canonical provider history. This journal records the
//! ordered UI frames after the last matching persistence checkpoint plus folded
//! ephemeral state. Its broadcast carries wake hints only; SQLite is authority.

use std::{
    collections::{BTreeMap, HashMap, HashSet},
    path::Path,
    sync::{
        atomic::{AtomicU64, Ordering},
        Arc, Mutex,
    },
    time::{Duration, Instant, SystemTime, UNIX_EPOCH},
};

use anyhow::{Context, Result};
use ocean_agent_sdk::AgentTurnEvent;
use ocean_core::{
    EventEnvelope, OceanEvent, SessionProjection, SessionProjectionFrame, SessionProjectionSource,
    SessionProjectionState, EVENT_ORIGIN_AGENT,
};
use rusqlite::{params, Connection, OptionalExtension};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use tokio::sync::broadcast;
use uuid::Uuid;

pub(crate) const DEFAULT_JOURNAL_BYTES: u64 = 256 * 1024 * 1024;
pub(crate) const DEFAULT_LEASE: Duration = Duration::from_secs(60);
const PAGE_LIMIT: usize = 256;

const SCHEMA: &str = r#"
CREATE TABLE IF NOT EXISTS session_projection_sessions (
  epoch TEXT NOT NULL,
  session_id TEXT NOT NULL,
  latest_seq INTEGER NOT NULL DEFAULT 0,
  checkpoint_seq INTEGER NOT NULL DEFAULT 0,
  checkpoint_revision INTEGER NOT NULL DEFAULT 0,
  state_json TEXT NOT NULL,
  PRIMARY KEY(epoch, session_id)
);
CREATE TABLE IF NOT EXISTS session_projection_events (
  epoch TEXT NOT NULL,
  session_id TEXT NOT NULL,
  seq INTEGER NOT NULL,
  source TEXT NOT NULL,
  event_json TEXT NOT NULL,
  encoded_bytes INTEGER NOT NULL,
  created_ms INTEGER NOT NULL,
  PRIMARY KEY(epoch, session_id, seq)
);
CREATE INDEX IF NOT EXISTS session_projection_events_age
  ON session_projection_events(epoch, created_ms);
"#;

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
struct FoldedState {
    active_turn: Option<Value>,
    last_turn_finished: Option<Value>,
    pending_permissions: BTreeMap<String, Value>,
    components: BTreeMap<String, Value>,
    browser_active: bool,
}

impl FoldedState {
    fn wire(self) -> SessionProjectionState {
        SessionProjectionState {
            active_turn: self.active_turn,
            last_turn_finished: self.last_turn_finished,
            pending_permissions: self.pending_permissions.into_values().collect(),
            components: self.components.into_values().collect(),
            browser_active: self.browser_active,
        }
    }

    fn fold_agent(&mut self, event: &AgentTurnEvent, value: &Value) {
        match event {
            AgentTurnEvent::TurnStarted { .. } => self.active_turn = Some(value.clone()),
            AgentTurnEvent::TurnFinished { .. } => {
                self.active_turn = None;
                self.last_turn_finished = Some(value.clone());
                self.browser_active = false;
            }
            AgentTurnEvent::ComponentRender { component_id, .. } => {
                self.components.insert(component_id.clone(), value.clone());
            }
            AgentTurnEvent::ComponentUnmount { component_id, .. } => {
                self.components.remove(component_id);
            }
            AgentTurnEvent::BrowserActivity { active, .. } => self.browser_active = *active,
            _ => {}
        }
    }

    fn fold_control(&mut self, envelope: &EventEnvelope, value: &Value) {
        let Some(permission_id) = envelope.permission_id else {
            return;
        };
        match envelope.event {
            OceanEvent::PermissionRequest { .. } => {
                self.pending_permissions
                    .insert(permission_id.to_string(), value.clone());
            }
            OceanEvent::PermissionDecision { .. } => {
                self.pending_permissions.remove(&permission_id.to_string());
            }
            _ => {}
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ProjectionCursor {
    epoch: String,
    session_hash: String,
    seq: u64,
}

impl ProjectionCursor {
    fn new(epoch: &str, session_id: &str, seq: u64) -> Self {
        Self {
            epoch: epoch.to_string(),
            session_hash: session_hash(session_id),
            seq,
        }
    }

    pub(crate) fn parse(raw: &str) -> std::result::Result<Self, ProjectionReset> {
        let mut parts = raw.split(':');
        if parts.next() != Some("sp1") {
            return Err(ProjectionReset::Malformed);
        }
        let (Some(epoch), Some(session_hash), Some(seq), None) =
            (parts.next(), parts.next(), parts.next(), parts.next())
        else {
            return Err(ProjectionReset::Malformed);
        };
        let seq = seq.parse().map_err(|_| ProjectionReset::Malformed)?;
        if epoch.is_empty() || session_hash.len() != 16 {
            return Err(ProjectionReset::Malformed);
        }
        Ok(Self {
            epoch: epoch.to_string(),
            session_hash: session_hash.to_string(),
            seq,
        })
    }
}

impl std::fmt::Display for ProjectionCursor {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "sp1:{}:{}:{}", self.epoch, self.session_hash, self.seq)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ProjectionReset {
    Malformed,
    WrongEpoch,
    WrongSession,
    Future,
    Retention,
    Faulted,
    RevisionMismatch,
}

impl ProjectionReset {
    pub(crate) fn reason(self) -> &'static str {
        match self {
            Self::Malformed => "malformed_cursor",
            Self::WrongEpoch => "daemon_epoch_changed",
            Self::WrongSession => "session_mismatch",
            Self::Future => "future_cursor",
            Self::Retention => "retention_boundary",
            Self::Faulted => "projection_store_fault",
            Self::RevisionMismatch => "snapshot_revision_not_ready",
        }
    }
}

#[derive(Clone)]
pub(crate) struct SessionProjectionStore {
    db: Arc<Mutex<Connection>>,
    epoch: Arc<str>,
    wakes: broadcast::Sender<String>,
    leases: Arc<Mutex<HashMap<String, Vec<Lease>>>>,
    faults: Arc<Mutex<HashSet<String>>>,
    logical_bytes: Arc<AtomicU64>,
    budget_bytes: u64,
    lease_duration: Duration,
}

#[derive(Clone, Copy)]
struct Lease {
    min_seq: u64,
    expires: Instant,
}

impl SessionProjectionStore {
    pub(crate) fn open(path: &Path) -> Result<Self> {
        let budget_bytes = std::env::var("OCEAN_SESSION_PROJECTION_JOURNAL_BYTES")
            .ok()
            .and_then(|raw| raw.parse::<u64>().ok())
            .filter(|value| *value > 0)
            .unwrap_or(DEFAULT_JOURNAL_BYTES);
        Self::open_with_config(path, budget_bytes, DEFAULT_LEASE)
    }

    fn open_with_config(path: &Path, budget_bytes: u64, lease_duration: Duration) -> Result<Self> {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).with_context(|| {
                format!("creating projection DB directory {}", parent.display())
            })?;
        }
        let db = Connection::open(path)
            .with_context(|| format!("opening session projection DB {}", path.display()))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600))
                .with_context(|| format!("securing session projection DB {}", path.display()))?;
        }
        db.execute_batch(
            "PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; PRAGMA foreign_keys=ON;",
        )?;
        db.execute_batch(SCHEMA)?;
        let logical_bytes = db.query_row(
            "SELECT COALESCE(SUM(encoded_bytes),0) FROM session_projection_events",
            [],
            |row| row.get::<_, u64>(0),
        )?;
        let (wakes, _) = broadcast::channel(1024);
        Ok(Self {
            db: Arc::new(Mutex::new(db)),
            epoch: Arc::from(Uuid::new_v4().to_string()),
            wakes,
            leases: Arc::new(Mutex::new(HashMap::new())),
            faults: Arc::new(Mutex::new(HashSet::new())),
            logical_bytes: Arc::new(AtomicU64::new(logical_bytes)),
            budget_bytes,
            lease_duration,
        })
    }

    pub(crate) fn subscribe(&self) -> broadcast::Receiver<String> {
        self.wakes.subscribe()
    }

    pub(crate) fn append_agent(&self, event: &AgentTurnEvent) -> Result<Option<ProjectionCursor>> {
        let Some(session_id) = event.session_id().map(|id| id.to_string()) else {
            return Ok(None);
        };
        if matches!(
            event,
            AgentTurnEvent::SurfacePatch { .. }
                | AgentTurnEvent::SlackCanvas { .. }
                | AgentTurnEvent::Extension { .. }
        ) {
            return Ok(None);
        }
        let value = serde_json::to_value(event)?;
        self.append(
            &session_id,
            SessionProjectionSource::Agent,
            value,
            |state, value| state.fold_agent(event, value),
        )
        .map(Some)
    }

    pub(crate) fn append_control(
        &self,
        envelope: &EventEnvelope,
    ) -> Result<Option<ProjectionCursor>> {
        if envelope.origin.as_deref() == Some(EVENT_ORIGIN_AGENT)
            || !matches!(
                envelope.event,
                OceanEvent::PermissionRequest { .. } | OceanEvent::PermissionDecision { .. }
            )
        {
            return Ok(None);
        }
        let Some(session_id) = envelope.session_id.map(|id| id.to_string()) else {
            return Ok(None);
        };
        let value = serde_json::to_value(envelope)?;
        self.append(
            &session_id,
            SessionProjectionSource::Control,
            value,
            |state, value| state.fold_control(envelope, value),
        )
        .map(Some)
    }

    fn append(
        &self,
        session_id: &str,
        source: SessionProjectionSource,
        event: Value,
        fold: impl FnOnce(&mut FoldedState, &Value),
    ) -> Result<ProjectionCursor> {
        let event_json = serde_json::to_string(&event)?;
        let created_ms = now_ms();
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction()?;
        let (latest, checkpoint_seq, checkpoint_revision, state_json) = load_row(
            &tx,
            &self.epoch,
            session_id,
        )?
        .unwrap_or((0, 0, 0, serde_json::to_string(&FoldedState::default())?));
        let seq = latest
            .checked_add(1)
            .context("session projection cursor exhausted")?;
        let mut state: FoldedState = serde_json::from_str(&state_json)?;
        fold(&mut state, &event);
        let state_json = serde_json::to_string(&state)?;
        tx.execute(
            "INSERT INTO session_projection_events(epoch,session_id,seq,source,event_json,encoded_bytes,created_ms) VALUES(?1,?2,?3,?4,?5,?6,?7)",
            params![&*self.epoch, session_id, seq, source_name(source), event_json, event_json.len() as u64, created_ms],
        )?;
        tx.execute(
            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET latest_seq=excluded.latest_seq,state_json=excluded.state_json",
            params![&*self.epoch, session_id, seq, checkpoint_seq, checkpoint_revision, state_json],
        )?;
        tx.commit()?;
        drop(db);
        self.logical_bytes
            .fetch_add(event_json.len() as u64, Ordering::Relaxed);
        let cursor = ProjectionCursor::new(&self.epoch, session_id, seq);
        let _ = self.wakes.send(session_id.to_string());
        // Ordinary appends only trigger pressure compaction; age-based
        // checkpoint compaction runs when a persistence boundary advances.
        if self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes {
            self.compact(true)?;
        }
        Ok(cursor)
    }

    pub(crate) fn checkpoint(&self, session_id: &str, revision: u64) -> Result<()> {
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction()?;
        let row = load_row(&tx, &self.epoch, session_id)?;
        let (latest, checkpoint_seq, checkpoint_revision, state_json) =
            row.unwrap_or((0, 0, 0, serde_json::to_string(&FoldedState::default())?));
        if revision < checkpoint_revision {
            anyhow::bail!("session projection checkpoint revision regressed");
        }
        let next_checkpoint_seq = if revision == checkpoint_revision {
            checkpoint_seq
        } else {
            latest
        };
        tx.execute(
            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET checkpoint_seq=excluded.checkpoint_seq,checkpoint_revision=excluded.checkpoint_revision",
            params![&*self.epoch, session_id, latest, next_checkpoint_seq, revision, state_json],
        )?;
        tx.commit()?;
        drop(db);
        self.compact(false)
    }

    pub(crate) fn snapshot(
        &self,
        session_id: &str,
        file_revision: u64,
    ) -> std::result::Result<SessionProjection, ProjectionReset> {
        if self.is_faulted(session_id) {
            return Err(ProjectionReset::Faulted);
        }
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let tx = db.transaction().map_err(|_| ProjectionReset::Faulted)?;
        let row = load_row(&tx, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?;
        let (latest, mut checkpoint_seq, mut checkpoint_revision, state_json) = row.unwrap_or((
            0,
            0,
            file_revision,
            serde_json::to_string(&FoldedState::default()).map_err(|_| ProjectionReset::Faulted)?,
        ));
        let state: FoldedState =
            serde_json::from_str(&state_json).map_err(|_| ProjectionReset::Faulted)?;
        if file_revision != checkpoint_revision {
            if file_revision > checkpoint_revision && state.active_turn.is_none() {
                checkpoint_revision = file_revision;
                checkpoint_seq = latest;
            } else {
                return Err(ProjectionReset::RevisionMismatch);
            }
        }
        tx.execute(
            "INSERT INTO session_projection_sessions(epoch,session_id,latest_seq,checkpoint_seq,checkpoint_revision,state_json) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(epoch,session_id) DO UPDATE SET checkpoint_seq=excluded.checkpoint_seq,checkpoint_revision=excluded.checkpoint_revision",
            params![&*self.epoch, session_id, latest, checkpoint_seq, checkpoint_revision, state_json],
        )
        .map_err(|_| ProjectionReset::Faulted)?;
        let pending = query_frames(&tx, &self.epoch, session_id, checkpoint_seq, latest)
            .map_err(|_| ProjectionReset::Faulted)?;
        tx.commit().map_err(|_| ProjectionReset::Faulted)?;
        drop(db);
        self.renew_lease(session_id, latest);
        Ok(SessionProjection {
            version: 1,
            cursor: ProjectionCursor::new(&self.epoch, session_id, latest).to_string(),
            checkpoint_revision,
            pending_events: pending,
            state: state.wire(),
        })
    }

    pub(crate) fn page_after(
        &self,
        session_id: &str,
        raw_cursor: &str,
    ) -> std::result::Result<Vec<SessionProjectionFrame>, ProjectionReset> {
        if self.is_faulted(session_id) {
            return Err(ProjectionReset::Faulted);
        }
        let cursor = ProjectionCursor::parse(raw_cursor)?;
        if cursor.epoch.as_str() != self.epoch.as_ref() {
            return Err(ProjectionReset::WrongEpoch);
        }
        if cursor.session_hash != session_hash(session_id) {
            return Err(ProjectionReset::WrongSession);
        }
        let db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let Some((latest, _, _, _)) =
            load_row(&db, &self.epoch, session_id).map_err(|_| ProjectionReset::Faulted)?
        else {
            if cursor.seq == 0 {
                return Ok(Vec::new());
            }
            return Err(ProjectionReset::Future);
        };
        if cursor.seq > latest {
            return Err(ProjectionReset::Future);
        }
        let earliest: Option<u64> = db
            .query_row(
                "SELECT MIN(seq) FROM session_projection_events WHERE epoch=?1 AND session_id=?2",
                params![&*self.epoch, session_id],
                |row| row.get(0),
            )
            .optional()
            .map_err(|_| ProjectionReset::Faulted)?
            .flatten();
        if cursor.seq < latest && earliest.is_none_or(|first| cursor.seq.saturating_add(1) < first)
        {
            return Err(ProjectionReset::Retention);
        }
        let through = cursor.seq.saturating_add(PAGE_LIMIT as u64);
        let frames = query_frames(
            &db,
            &self.epoch,
            session_id,
            cursor.seq,
            through.min(latest),
        )
        .map_err(|_| ProjectionReset::Faulted)?;
        drop(db);
        let sent = frames
            .last()
            .and_then(|frame| ProjectionCursor::parse(&frame.cursor).ok())
            .map(|cursor| cursor.seq)
            .unwrap_or(cursor.seq);
        self.renew_lease(session_id, sent);
        Ok(frames)
    }

    pub(crate) fn fault(&self, session_id: &str, error: &anyhow::Error) {
        self.faults
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .insert(session_id.to_string());
        tracing::error!(session_id, error = %error, "session projection continuity lost");
        let _ = self.wakes.send(session_id.to_string());
    }

    fn is_faulted(&self, session_id: &str) -> bool {
        self.faults
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .contains(session_id)
    }

    fn renew_lease(&self, session_id: &str, min_seq: u64) {
        self.leases
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .entry(session_id.to_string())
            .or_default()
            .push(Lease {
                min_seq,
                expires: Instant::now() + self.lease_duration,
            });
    }

    fn compact(&self, pressure_only: bool) -> Result<()> {
        let now = Instant::now();
        let leases = {
            let mut leases = self
                .leases
                .lock()
                .unwrap_or_else(|poison| poison.into_inner());
            leases.retain(|_, session_leases| {
                session_leases.retain(|lease| lease.expires > now);
                !session_leases.is_empty()
            });
            leases.clone()
        };
        let cutoff_ms = now_ms().saturating_sub(self.lease_duration.as_millis() as i64);
        let pressure = self.logical_bytes.load(Ordering::Relaxed) > self.budget_bytes;
        if pressure_only && !pressure {
            return Ok(());
        }
        let mut db = self.db.lock().unwrap_or_else(|poison| poison.into_inner());
        let rows = {
            let mut stmt = db.prepare(
                "SELECT session_id,checkpoint_seq FROM session_projection_sessions WHERE epoch=?1",
            )?;
            let collected = stmt
                .query_map([&*self.epoch], |row| {
                    Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?))
                })?
                .collect::<std::result::Result<Vec<_>, _>>()?;
            collected
        };
        let tx = db.transaction()?;
        for (session_id, checkpoint_seq) in rows {
            let protected = leases
                .get(&session_id)
                .and_then(|session_leases| session_leases.iter().map(|lease| lease.min_seq).min())
                .unwrap_or(checkpoint_seq);
            let through = checkpoint_seq.min(protected);
            if pressure {
                tx.execute(
                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3",
                    params![&*self.epoch, session_id, through],
                )?;
            } else {
                tx.execute(
                    "DELETE FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq<=?3 AND created_ms<=?4",
                    params![&*self.epoch, session_id, through, cutoff_ms],
                )?;
            }
        }
        if pressure {
            tx.execute(
                "DELETE FROM session_projection_events WHERE epoch<>?1",
                [&*self.epoch],
            )?;
        }
        tx.commit()?;
        let remaining = db.query_row(
            "SELECT COALESCE(SUM(encoded_bytes),0) FROM session_projection_events",
            [],
            |row| row.get::<_, u64>(0),
        )?;
        self.logical_bytes.store(remaining, Ordering::Relaxed);
        Ok(())
    }
}

fn load_row(
    db: &Connection,
    epoch: &str,
    session_id: &str,
) -> rusqlite::Result<Option<(u64, u64, u64, String)>> {
    db.query_row(
        "SELECT latest_seq,checkpoint_seq,checkpoint_revision,state_json FROM session_projection_sessions WHERE epoch=?1 AND session_id=?2",
        params![epoch, session_id],
        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
    )
    .optional()
}

fn query_frames(
    db: &Connection,
    epoch: &str,
    session_id: &str,
    after: u64,
    through: u64,
) -> Result<Vec<SessionProjectionFrame>> {
    let mut stmt = db.prepare(
        "SELECT seq,source,event_json FROM session_projection_events WHERE epoch=?1 AND session_id=?2 AND seq>?3 AND seq<=?4 ORDER BY seq ASC",
    )?;
    let rows = stmt.query_map(params![epoch, session_id, after, through], |row| {
        Ok((
            row.get::<_, u64>(0)?,
            row.get::<_, String>(1)?,
            row.get::<_, String>(2)?,
        ))
    })?;
    let mut frames = Vec::new();
    for row in rows {
        let (seq, source, event_json) = row?;
        frames.push(SessionProjectionFrame {
            cursor: ProjectionCursor::new(epoch, session_id, seq).to_string(),
            source: if source == "agent" {
                SessionProjectionSource::Agent
            } else {
                SessionProjectionSource::Control
            },
            event: serde_json::from_str(&event_json)?,
        });
    }
    Ok(frames)
}

fn source_name(source: SessionProjectionSource) -> &'static str {
    match source {
        SessionProjectionSource::Agent => "agent",
        SessionProjectionSource::Control => "control",
    }
}

fn session_hash(session_id: &str) -> String {
    let digest = Sha256::digest(session_id.as_bytes());
    digest[..8]
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn now_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .min(i64::MAX as u128) as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use ocean_agent_sdk::{AgentSessionId, AgentTurnId};
    use tempfile::tempdir;

    fn store(lease: Duration) -> SessionProjectionStore {
        let dir = tempdir().unwrap();
        // Keep the temporary directory alive for the process-long test by using
        // a database file whose open handle remains valid after unlink on Unix.
        SessionProjectionStore::open_with_config(
            &dir.path().join("projection.db"),
            1024 * 1024,
            lease,
        )
        .unwrap()
    }

    #[cfg(unix)]
    #[test]
    fn projection_database_is_owner_only() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempdir().unwrap();
        let path = dir.path().join("projection.db");
        let _store = SessionProjectionStore::open(&path).unwrap();
        assert_eq!(
            std::fs::metadata(path).unwrap().permissions().mode() & 0o777,
            0o600
        );
    }

    #[test]
    fn cursors_are_session_scoped_contiguous_and_surface_patch_is_excluded() {
        let store = store(DEFAULT_LEASE);
        let a = AgentSessionId::new_v4();
        let b = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let first = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: a,
                turn_id: turn,
                delta: "a".into(),
            })
            .unwrap()
            .unwrap();
        let second = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: a,
                turn_id: turn,
                delta: "b".into(),
            })
            .unwrap()
            .unwrap();
        let other = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: b,
                turn_id: turn,
                delta: "x".into(),
            })
            .unwrap()
            .unwrap();
        assert_eq!(first.seq, 1);
        assert_eq!(second.seq, 2);
        assert_eq!(other.seq, 1);
        let excluded = store
            .append_agent(&AgentTurnEvent::SurfacePatch {
                session_id: a,
                turn_id: turn,
                canvas_id: ocean_agent_sdk::surface::CanvasId::new("main"),
                patches: vec![],
            })
            .unwrap();
        assert!(excluded.is_none());
        let snapshot = store.snapshot(&a.to_string(), 0).unwrap();
        assert_eq!(snapshot.pending_events.len(), 2);
        assert!(snapshot.cursor.ends_with(":2"));
    }

    #[test]
    fn folded_state_tracks_turn_component_browser_and_permission() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        store
            .append_agent(&AgentTurnEvent::TurnStarted {
                session_id: session,
                turn_id: turn,
                model: Some("test".into()),
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::ComponentRender {
                session_id: session,
                component_id: "card".into(),
                kind: "markdown".into(),
                props: serde_json::json!({"text":"one"}),
                replace: false,
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::BrowserActivity {
                session_id: session,
                active: true,
            })
            .unwrap();
        let permission_id = ocean_core::PermissionId::new_v4();
        let mut request = EventEnvelope::new(OceanEvent::PermissionRequest {
            tool: "bash".into(),
            reason: "approval".into(),
            args: serde_json::json!({}),
        });
        request.session_id = Some(session.0);
        request.permission_id = Some(permission_id);
        store.append_control(&request).unwrap();
        let state = store.snapshot(&session.to_string(), 0).unwrap().state;
        assert!(state.active_turn.is_some());
        assert!(state.browser_active);
        assert_eq!(state.components.len(), 1);
        assert_eq!(state.pending_permissions.len(), 1);
        let mut decision = EventEnvelope::new(OceanEvent::PermissionDecision {
            allowed: true,
            reason: None,
        });
        decision.session_id = request.session_id;
        decision.permission_id = Some(permission_id);
        store.append_control(&decision).unwrap();
        store
            .append_agent(&AgentTurnEvent::TurnFinished {
                session_id: session,
                turn_id: turn,
                status: ocean_agent_sdk::AgentTurnStatus::Completed,
                error: None,
                wall_ms: Some(1),
                output_tokens: None,
                input_tokens: None,
                cache_read_tokens: None,
                tokens_per_second: None,
                context_usage: None,
            })
            .unwrap();
        let state = store.snapshot(&session.to_string(), 0).unwrap().state;
        assert!(state.active_turn.is_none());
        assert!(state.last_turn_finished.is_some());
        assert!(!state.browser_active);
        assert!(state.pending_permissions.is_empty());
    }

    #[test]
    fn concurrent_appends_allocate_one_contiguous_session_sequence() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let mut workers = Vec::new();
        for worker in 0..4 {
            let store = store.clone();
            workers.push(std::thread::spawn(move || {
                for index in 0..25 {
                    store
                        .append_agent(&AgentTurnEvent::AssistantTextDelta {
                            session_id: session,
                            turn_id: turn,
                            delta: format!("{worker}:{index}"),
                        })
                        .unwrap();
                }
            }));
        }
        for worker in workers {
            worker.join().unwrap();
        }
        let snapshot = store.snapshot(&session.to_string(), 0).unwrap();
        assert_eq!(snapshot.pending_events.len(), 100);
        let sequences = snapshot
            .pending_events
            .iter()
            .map(|frame| ProjectionCursor::parse(&frame.cursor).unwrap().seq)
            .collect::<Vec<_>>();
        assert_eq!(sequences, (1..=100).collect::<Vec<_>>());
    }

    #[test]
    fn cursor_validation_resets_wrong_epoch_session_future_and_malformed() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4().to_string();
        let snapshot = store.snapshot(&session, 0).unwrap();
        assert_eq!(
            store.page_after(&session, "bad").unwrap_err(),
            ProjectionReset::Malformed
        );
        let wrong_epoch = snapshot
            .cursor
            .replacen(&*store.epoch, &Uuid::new_v4().to_string(), 1);
        assert_eq!(
            store.page_after(&session, &wrong_epoch).unwrap_err(),
            ProjectionReset::WrongEpoch
        );
        let wrong_session = AgentSessionId::new_v4().to_string();
        assert_eq!(
            store
                .page_after(&wrong_session, &snapshot.cursor)
                .unwrap_err(),
            ProjectionReset::WrongSession
        );
        let future = ProjectionCursor::new(&store.epoch, &session, 1).to_string();
        assert_eq!(
            store.page_after(&session, &future).unwrap_err(),
            ProjectionReset::Future
        );
    }

    #[test]
    fn subscribe_before_page_catches_append_and_pages_durable_row() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let snapshot = store.snapshot(&session.to_string(), 0).unwrap();
        let mut wakes = store.subscribe();
        store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: session,
                turn_id: turn,
                delta: "after snapshot".into(),
            })
            .unwrap();
        assert_eq!(wakes.try_recv().unwrap(), session.to_string());
        let page = store
            .page_after(&session.to_string(), &snapshot.cursor)
            .unwrap();
        assert_eq!(page.len(), 1);
        assert_eq!(page[0].event["delta"], "after snapshot");
    }

    #[test]
    fn daemon_restart_changes_epoch_and_clears_transient_fold() {
        let dir = tempdir().unwrap();
        let path = dir.path().join("projection.db");
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let first =
            SessionProjectionStore::open_with_config(&path, 1024 * 1024, DEFAULT_LEASE).unwrap();
        first
            .append_agent(&AgentTurnEvent::ThinkingDelta {
                session_id: session,
                turn_id: turn,
                delta: "transient".into(),
            })
            .unwrap();
        let old = first.snapshot(&session.to_string(), 7).unwrap();
        drop(first);

        let second =
            SessionProjectionStore::open_with_config(&path, 1024 * 1024, DEFAULT_LEASE).unwrap();
        assert_eq!(
            second
                .page_after(&session.to_string(), &old.cursor)
                .unwrap_err(),
            ProjectionReset::WrongEpoch
        );
        let fresh = second.snapshot(&session.to_string(), 7).unwrap();
        assert!(fresh.pending_events.is_empty());
        assert!(fresh.state.active_turn.is_none());
        assert_eq!(fresh.checkpoint_revision, 7);
    }

    #[test]
    fn active_attach_lease_protects_checkpointed_catchup_under_pressure() {
        let dir = tempdir().unwrap();
        let store = SessionProjectionStore::open_with_config(
            &dir.path().join("projection.db"),
            1,
            DEFAULT_LEASE,
        )
        .unwrap();
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let attached = store.snapshot(&session.to_string(), 0).unwrap();
        store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: session,
                turn_id: turn,
                delta: "must survive".into(),
            })
            .unwrap();
        store.checkpoint(&session.to_string(), 1).unwrap();
        let page = store
            .page_after(&session.to_string(), &attached.cursor)
            .unwrap();
        assert_eq!(page.len(), 1);
    }

    #[test]
    fn checkpoint_compacts_only_committed_rows_after_lease_expiry() {
        let store = store(Duration::ZERO);
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: session,
                turn_id: turn,
                delta: "done".into(),
            })
            .unwrap();
        store.checkpoint(&session.to_string(), 1).unwrap();
        store.compact(false).unwrap();
        let snapshot = store.snapshot(&session.to_string(), 1).unwrap();
        assert!(snapshot.pending_events.is_empty());
        let old = ProjectionCursor::new(&store.epoch, &session.to_string(), 0).to_string();
        assert_eq!(
            store.page_after(&session.to_string(), &old).unwrap_err(),
            ProjectionReset::Retention
        );
    }
}

