    AssistantTextDelta {
        session_id: AgentSessionId,
        turn_id: AgentTurnId,
        delta: String,
    },
    /// Incremental assistant thinking delta (extended-thinking models only).
    /// Clients should display this in a separate, collapsed surface from the
    /// main assistant text — it is not part of the public turn output.
    ThinkingDelta {
        session_id: AgentSessionId,
        turn_id: AgentTurnId,
        delta: String,
    },
    /// A tool call has been dispatched.
    ToolCallStarted {
        session_id: AgentSessionId,
        turn_id: AgentTurnId,
        call: ToolCall,
    },
    /// Incremental output from a running tool call.
    ToolCallChunk {
        session_id: AgentSessionId,
        turn_id: AgentTurnId,
        call_id: ToolCallId,
        chunk: String,
    },
    /// A tool call has completed.
    ToolCallFinished {
        session_id: AgentSessionId,
        turn_id: AgentTurnId,
        call_id: ToolCallId,
        result: ToolResult,
    },
    /// The turn has ended.
    TurnFinished {
        session_id: AgentSessionId,
        turn_id: AgentTurnId,
        status: AgentTurnStatus,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        error: Option<String>,
