            session_id: None,
            message: Message::user_text("x"),
        },
        AgentEvent::UserMessage {
            session_id: None,
            message: Message::user_text("x"),
        },
    ];
    for ev in &filtered {
        assert_eq!(
            classify_agent_event(ev),
            RelayClass::Filtered,
